    func zeroEnabled() {
        #expect(!LargeDownloadConfirmation.needsConfirmation(chapterCount: 0, isEnabled: true))
    }

    @Test("500 chapters with the setting off — catches ignoring the setting")
    func largeDisabled() {
        #expect(!LargeDownloadConfirmation.needsConfirmation(chapterCount: 500, isEnabled: false))
