//
//  ConfirmLargeDownloadsSettingTests.swift
//  Aidoku
//

import AidokuRunner
@testable import Aidoku
import Testing

struct ConfirmLargeDownloadsSettingTests {
    @Test func downloadSettingsListsToggleAfterParallel() {
        let keys = Settings.downloadSettings.map(\.key)
        let key = AppSettings.downloads.confirmLargeDownloads.key
        #expect(keys.contains(key))
        #expect(keys.firstIndex(of: key) == (keys.firstIndex(of: AppSettings.downloads.parallel.key) ?? -2) + 1)

        let setting = Settings.downloadSettings.first { $0.key == key }
        guard case .toggle = setting?.value else {
            Issue.record("expected a toggle entry")
            return
        }
    }

    @Test func settingKeyMatchesAccessibilityIdentifier() {
        #expect(
            AppSettings.downloads.confirmLargeDownloads.key
                == LargeDownloadConfirmation.settingAccessibilityIdentifier
        )
    }

    @Test func registersKeyWithDefaultFalse() {
        let entry = AppSettings.downloads.keys.first {
            $0.key == AppSettings.downloads.confirmLargeDownloads.key
        }
        #expect(entry?.defaultObject as? Bool == false)
    }
}
EOF
